package com.glassbox.checkers.rule; import com.glassbox.checkers.domain.*; import com.glassbox.chess.domain.*; import java.util.*;
/** Basic American checkers move generation with mandatory captures and reversible moves. */
public final class CheckersRules{private CheckersRules(){}public static List<CheckersMove> getLegalMoves(CheckersBoard b,Color turn){List<CheckersMove> captures=new ArrayList<>(),quiet=new ArrayList<>();for(int f=0;f<8;f++)for(int r=0;r<8;r++){Position p=new Position(f,r);CheckersPiece piece=b.getPieceAt(p);if(piece==null||piece.getColor()!=turn)continue;int[] dirs=piece.isKing()?new int[]{-1,1}:new int[]{turn==Color.WHITE?-1:1};for(int dr:dirs)for(int df:new int[]{-1,1}){Position one=new Position(f+df,r+dr);if(!b.isValid(one))continue;CheckersPiece target=b.getPieceAt(one);if(target==null)quiet.add(new CheckersMove(p,one,piece,null,null,piece.isKing()));else if(target.getColor()!=turn){Position land=new Position(f+2*df,r+2*dr);if(b.isValid(land)&&b.getPieceAt(land)==null)captures.add(new CheckersMove(p,land,piece,target,one,piece.isKing()));}}}return captures.isEmpty()?quiet:captures;}
public static void applyMove(CheckersBoard b,CheckersMove m){b.setPieceAt(m.getFrom(),null);if(m.getCapturedPos()!=null)b.setPieceAt(m.getCapturedPos(),null);b.setPieceAt(m.getTo(),m.getMovedPiece());int last=m.getMovedPiece().getColor()==Color.WHITE?0:7;if(m.getTo().getRank()==last)m.getMovedPiece().makeKing();}
public static void undoMove(CheckersBoard b,CheckersMove m){b.setPieceAt(m.getTo(),null);b.setPieceAt(m.getFrom(),m.getMovedPiece());if(m.getCapturedPiece()!=null)b.setPieceAt(m.getCapturedPos(),m.getCapturedPiece());m.getMovedPiece().setKing(m.wasKingBefore());} }
